using System;

namespace RoboFactory.Sim.EditorTools
{
    /// <summary>
    /// Procedural textures of the boxes of the public version (100 % generated by code, no image asset):
    ///   - cardboard box (B big, C small): kraft fibres, corrugation, folded edges, a dark band all around with
    ///     handling pictograms, packing tape on the top coming down two sides, a square code, a barcode sticker,
    ///     a hand hole and the type letter;
    ///   - wooden crate (A): frame of planks around a strand-board panel, nails, stencilled pictograms, square code
    ///     and type letter.
    /// Everything is drawn by this code (own simple pictograms, codes that encode nothing).
    /// Pure C# (RGBA bytes, row 0 = bottom like Unity textures) so it can be built and checked outside Unity.
    /// </summary>
    public static class BoxTextures
    {
        public const int Size = 256;

        public sealed class Image
        {
            public readonly int W, H;
            public readonly byte[] Rgba;
            public Image(int w, int h) { W = w; H = h; Rgba = new byte[w * h * 4]; }

            public void Set(int x, int y, float r, float g, float b)
            {
                if (x < 0 || y < 0 || x >= W || y >= H) return;
                int i = (y * W + x) * 4;
                Rgba[i] = B(r); Rgba[i + 1] = B(g); Rgba[i + 2] = B(b); Rgba[i + 3] = 255;
            }

            public void Get(int x, int y, out float r, out float g, out float b)
            {
                int i = (Math.Min(H - 1, Math.Max(0, y)) * W + Math.Min(W - 1, Math.Max(0, x))) * 4;
                r = Rgba[i] / 255f; g = Rgba[i + 1] / 255f; b = Rgba[i + 2] / 255f;
            }

            /// <summary>Paints (r,g,b) over the pixel with opacity a.</summary>
            public void Blend(int x, int y, float r, float g, float b, float a)
            {
                if (x < 0 || y < 0 || x >= W || y >= H) return;
                Get(x, y, out float pr, out float pg, out float pb);
                Set(x, y, pr + (r - pr) * a, pg + (g - pg) * a, pb + (b - pb) * a);
            }

            /// <summary>Multiplies the pixel by f.</summary>
            public void Shade(int x, int y, float f)
            {
                if (x < 0 || y < 0 || x >= W || y >= H) return;
                Get(x, y, out float r, out float g, out float b);
                Set(x, y, r * f, g * f, b * f);
            }

            /// <summary>Rectangle in texture space, origin top-left (v down) for readability of the layouts.</summary>
            public void Rect(float u0, float v0, float u1, float v1, float r, float g, float b, float a = 1f)
            {
                int x0 = (int)(u0 * W), x1 = (int)(u1 * W), y0 = (int)(v0 * H), y1 = (int)(v1 * H);
                for (int y = y0; y < y1; y++)
                    for (int x = x0; x < x1; x++)
                        Blend(x, H - 1 - y, r, g, b, a);
            }

            private static byte B(float v) => (byte)Math.Max(0, Math.Min(255, (int)Math.Round(v * 255f)));
        }

        // ------------------------------------------------------------------ noise

        private static float Hash(int x, int y, int seed)
        {
            unchecked
            {
                uint h = (uint)(x * 374761393 + y * 668265263 + seed * 1442695041);
                h = (h ^ (h >> 13)) * 1274126177u;
                h ^= h >> 16;
                return (h & 0xFFFFFF) / (float)0xFFFFFF;
            }
        }

        private static float Smooth(float t) => t * t * (3f - 2f * t);

        /// <summary>Value noise, tileable over <paramref name="period"/> cells.</summary>
        private static float Noise(float x, float y, int seed, int period)
        {
            int xi = (int)Math.Floor(x), yi = (int)Math.Floor(y);
            float fx = Smooth(x - xi), fy = Smooth(y - yi);
            int x0 = Mod(xi, period), x1 = Mod(xi + 1, period), y0 = Mod(yi, period), y1 = Mod(yi + 1, period);
            float a = Hash(x0, y0, seed), b = Hash(x1, y0, seed), c = Hash(x0, y1, seed), d = Hash(x1, y1, seed);
            return a + (b - a) * fx + (c - a) * fy + (a - b - c + d) * fx * fy;
        }

        private static float Fbm(float x, float y, int seed, int period)
        {
            float sum = 0f, amp = .5f, norm = 0f;
            for (int o = 0; o < 4; o++)
            {
                sum += Noise(x, y, seed + o * 17, period) * amp;
                norm += amp;
                x *= 2f; y *= 2f; period *= 2; amp *= .5f;
            }
            return sum / norm;
        }

        private static int Mod(int a, int m) => ((a % m) + m) % m;

        // ------------------------------------------------------------------ drawing helpers (u, v from the top-left)

        private static void Disc(Image img, float cu, float cv, float radius, float r, float g, float b, float a = 1f)
        {
            int x0 = (int)((cu - radius) * img.W), x1 = (int)((cu + radius) * img.W);
            int y0 = (int)((cv - radius) * img.H), y1 = (int)((cv + radius) * img.H);
            float rr = radius * img.W;
            for (int y = y0; y <= y1; y++)
                for (int x = x0; x <= x1; x++)
                {
                    float dx = x + .5f - cu * img.W, dy = y + .5f - cv * img.H;
                    if (dx * dx + dy * dy <= rr * rr) img.Blend(x, img.H - 1 - y, r, g, b, a);
                }
        }

        private static void Line(Image img, float u0, float v0, float u1, float v1, float width, float r, float g, float b, float a = 1f)
        {
            int steps = (int)(Math.Max(Math.Abs(u1 - u0), Math.Abs(v1 - v0)) * img.W * 2f) + 1;
            for (int i = 0; i <= steps; i++)
            {
                float t = i / (float)steps;
                Disc(img, u0 + (u1 - u0) * t, v0 + (v1 - v0) * t, width / 2f, r, g, b, a);
            }
        }

        /// <summary>Generic square code (random modules with three corner squares): looks like a 2D code, encodes nothing.</summary>
        private static void SquareCode(Image img, float u, float v, float size, int seed)
        {
            const int n = 21;
            float m = size / n;
            img.Rect(u - m, v - m, u + size + m, v + size + m, .96f, .96f, .93f);
            for (int row = 0; row < n; row++)
                for (int col = 0; col < n; col++)
                {
                    bool finder = (row < 7 && col < 7) || (row < 7 && col >= n - 7) || (row >= n - 7 && col < 7);
                    bool on;
                    if (finder)
                    {
                        int rr = row < 7 ? row : row - (n - 7), cc = col < 7 ? col : col - (n - 7);
                        on = rr == 0 || rr == 6 || cc == 0 || cc == 6 || (rr >= 2 && rr <= 4 && cc >= 2 && cc <= 4);
                    }
                    else on = Hash(row, col, seed + 101) < .48f;
                    if (on) img.Rect(u + col * m, v + row * m, u + (col + 1) * m, v + (row + 1) * m, .08f, .08f, .08f);
                }
        }

        /// <summary>Barcode sticker.</summary>
        private static void BarcodeLabel(Image img, float u0, float v0, float u1, float v1, int seed)
        {
            img.Rect(u0 + .006f, v0 + .008f, u1 + .006f, v1 + .008f, 0f, 0f, 0f, .15f);
            img.Rect(u0, v0, u1, v1, .96f, .96f, .93f);
            float bu = u0 + .02f;
            int bar = 0;
            while (bu < u1 - .025f)
            {
                float w = (1 + (int)(Hash(bar, 9, seed) * 3f)) * .004f;
                if (bar % 2 == 0) img.Rect(bu, v0 + (v1 - v0) * .18f, bu + w, v1 - (v1 - v0) * .3f, .08f, .08f, .08f);
                bu += w;
                bar++;
            }
            for (int i = 0; i < 8; i++)
                img.Rect(u0 + .025f + i * (u1 - u0 - .05f) / 8f, v1 - (v1 - v0) * .22f, u0 + .025f + i * (u1 - u0 - .05f) / 8f + .012f, v1 - (v1 - v0) * .1f, .3f, .3f, .3f);
        }

        // ------------------------------------------------------------------ handling pictograms (own simple drawings)

        private static void PictoUp(Image img, float u, float v, float s, float r, float g, float b)
        {
            for (int k = 0; k < 2; k++)
            {
                float cu = u + s * (.28f + k * .44f);
                Line(img, cu, v + s * .35f, cu, v + s * .85f, s * .1f, r, g, b);
                Line(img, cu, v + s * .15f, cu - s * .15f, v + s * .38f, s * .1f, r, g, b);
                Line(img, cu, v + s * .15f, cu + s * .15f, v + s * .38f, s * .1f, r, g, b);
            }
            Line(img, u + s * .1f, v + s * .92f, u + s * .9f, v + s * .92f, s * .08f, r, g, b);
        }

        private static void PictoGlass(Image img, float u, float v, float s, float r, float g, float b)
        {
            Line(img, u + s * .25f, v + s * .12f, u + s * .32f, v + s * .45f, s * .08f, r, g, b);
            Line(img, u + s * .75f, v + s * .12f, u + s * .68f, v + s * .45f, s * .08f, r, g, b);
            Line(img, u + s * .32f, v + s * .45f, u + s * .68f, v + s * .45f, s * .08f, r, g, b);
            Line(img, u + s * .25f, v + s * .12f, u + s * .75f, v + s * .12f, s * .08f, r, g, b);
            Line(img, u + s * .5f, v + s * .45f, u + s * .5f, v + s * .82f, s * .08f, r, g, b);
            Line(img, u + s * .3f, v + s * .85f, u + s * .7f, v + s * .85f, s * .09f, r, g, b);
            Line(img, u + s * .45f, v + s * .2f, u + s * .55f, v + s * .32f, s * .05f, r, g, b);   // crack
        }

        private static void PictoUmbrella(Image img, float u, float v, float s, float r, float g, float b)
        {
            for (int i = 0; i <= 24; i++)
            {
                double ang = Math.PI * i / 24.0;
                float x = u + s * (.5f - .38f * (float)Math.Cos(ang)), y = v + s * (.48f - .3f * (float)Math.Sin(ang));
                Line(img, x, y, u + s * .5f, v + s * .48f, s * .05f, r, g, b);
            }
            Line(img, u + s * .5f, v + s * .48f, u + s * .5f, v + s * .82f, s * .07f, r, g, b);
            Line(img, u + s * .5f, v + s * .82f, u + s * .4f, v + s * .86f, s * .07f, r, g, b);
            Disc(img, u + s * .2f, v + s * .1f, s * .04f, r, g, b);
            Disc(img, u + s * .5f, v + s * .04f, s * .04f, r, g, b);
            Disc(img, u + s * .8f, v + s * .1f, s * .04f, r, g, b);
        }

        private static void PictoRow(Image img, float u, float v, float s, float r, float g, float b)
        {
            float pad = s * .12f;
            for (int i = 0; i < 3; i++)
            {
                float cu = u + i * (s + pad);
                img.Rect(cu, v, cu + s, v + .006f, r, g, b);
                img.Rect(cu, v + s - .006f, cu + s, v + s, r, g, b);
                img.Rect(cu, v, cu + .006f, v + s, r, g, b);
                img.Rect(cu + s - .006f, v, cu + s, v + s, r, g, b);
                float inner = s * .8f, o = s * .1f;
                if (i == 0) PictoGlass(img, cu + o, v + o, inner, r, g, b);
                else if (i == 1) PictoUmbrella(img, cu + o, v + o, inner, r, g, b);
                else PictoUp(img, cu + o, v + o, inner, r, g, b);
            }
        }

        // ------------------------------------------------------------------ cardboard

        public enum CardboardFace { Top, SideTape, SideLabel }

        private static readonly float[] BandColor = { .36f, .24f, .13f };

        /// <summary>Kraft cardboard of the given base colour.</summary>
        public static Image Cardboard(float r, float g, float b, CardboardFace face, char letter, int seed)
        {
            var img = new Image(Size, Size);
            for (int y = 0; y < Size; y++)
                for (int x = 0; x < Size; x++)
                {
                    float n = Fbm(x / 32f, y / 32f, seed, 8);
                    float fibre = Hash(x, y, seed + 7) < .03f ? .9f : 1f;                    // dark fibres
                    float flute = 1f - .02f * (float)Math.Abs(Math.Sin(y * Math.PI / 5f));   // corrugation
                    float f = (.93f + .1f * n) * fibre * flute;
                    int d = Math.Min(Math.Min(x, Size - 1 - x), Math.Min(y, Size - 1 - y));
                    if (d < 8) f *= .84f + .16f * d / 8f;                                      // folded edges
                    img.Set(x, y, r * f, g * f, b * f);
                }

            float tr = Lerp(r, .7f, .35f), tg = Lerp(g, .52f, .35f), tb = Lerp(b, .28f, .35f);    // packing tape
            float cr = Lerp(r, 1f, .55f), cg = Lerp(g, .95f, .55f), cb = Lerp(b, .82f, .55f);     // cream print on the band
            switch (face)
            {
                case CardboardFace.Top:
                    Seam(img, .5f);
                    Tape(img, .5f, .22f, 0f, 1f, tr, tg, tb, seed);
                    break;
                case CardboardFace.SideTape:
                    Tape(img, .5f, .22f, 0f, .2f, tr, tg, tb, seed);                     // tape coming down from the top
                    Band(img, seed);
                    SquareCode(img, .1f, .14f, .17f, seed);
                    PictoRow(img, .58f, .585f, .1f, cr, cg, cb);
                    break;
                case CardboardFace.SideLabel:
                    HandHole(img, .5f, .17f);
                    Band(img, seed);
                    BarcodeLabel(img, .08f, .34f, .42f, .46f, seed);
                    PictoRow(img, .58f, .585f, .1f, cr, cg, cb);
                    // small type code in the corner of the label side
                    img.Rect(.82f, .76f, .92f, .9f, .09f, .07f, .05f, .85f);
                    Letter(img, letter, .835f, .775f, .07f, .11f, cr, cg, cb);
                    break;
            }
            return img;
        }

        /// <summary>Dark brown band printed / taped all around the box.</summary>
        private static void Band(Image img, int seed)
        {
            float v0 = .56f, v1 = .74f;
            int y0 = img.H - (int)(v1 * img.H), y1 = img.H - 1 - (int)(v0 * img.H);
            for (int y = y0; y <= y1; y++)
                for (int x = 0; x < img.W; x++)
                {
                    float n = .94f + .1f * Noise(x / 6f, y / 30f, seed + 21, 64);
                    img.Blend(x, y, BandColor[0] * n, BandColor[1] * n, BandColor[2] * n, .93f);
                }
            for (int x = 0; x < img.W; x++) { img.Shade(x, y0, .8f); img.Shade(x, y1, .8f); }
        }

        /// <summary>Hand hole cut in the side.</summary>
        private static void HandHole(Image img, float cu, float cv)
        {
            float w = .13f, h = .028f;
            Disc(img, cu - w, cv, h, .12f, .09f, .06f);
            Disc(img, cu + w, cv, h, .12f, .09f, .06f);
            img.Rect(cu - w, cv - h, cu + w, cv + h, .12f, .09f, .06f);
            // pressed rim
            for (int x = (int)((cu - w) * img.W); x <= (int)((cu + w) * img.W); x++)
                img.Shade(x, img.H - 1 - (int)((cv + h + .008f) * img.H), .85f);
        }

        private static void Seam(Image img, float u)
        {
            int x = (int)(u * img.W);
            for (int y = 0; y < img.H; y++)
            {
                img.Shade(x - 1, y, .55f);
                img.Shade(x, y, .45f);
                img.Shade(x + 1, y, .7f);
            }
        }

        /// <summary>Glossy packing tape, vertical band centred on u, between v0 and v1 (from the top).</summary>
        private static void Tape(Image img, float u, float width, float v0, float v1, float r, float g, float b, int seed)
        {
            int x0 = (int)((u - width / 2f) * img.W), x1 = (int)((u + width / 2f) * img.W);
            int yTop = img.H - 1 - (int)(v0 * img.H), yBottom = img.H - (int)(v1 * img.H);
            for (int y = yBottom; y <= yTop; y++)
                for (int x = x0; x <= x1; x++)
                {
                    float streak = .96f + .06f * Noise(x / 3f, y / 60f, seed + 3, 256);
                    float shine = 1f + .08f * (float)Math.Max(0, Math.Cos((x - x0) / (float)(x1 - x0) * Math.PI * 2f - 1f));
                    img.Blend(x, y, r * streak * shine, g * streak * shine, b * streak * shine, .8f);
                }
            for (int y = yBottom; y <= yTop; y++) { img.Shade(x0, y, .8f); img.Shade(x1, y, .8f); }
            if (v1 < 1f)
                for (int x = x0; x <= x1; x++)
                {
                    int jag = (int)(Hash(x / 3, 0, seed + 11) * 4f);
                    img.Shade(x, yBottom + jag, .85f);
                }
        }

        // 5×7 block letters for the type codes
        private static readonly string[] GlyphA = { ".###.", "#...#", "#...#", "#####", "#...#", "#...#", "#...#" };
        private static readonly string[] GlyphB = { "####.", "#...#", "#...#", "####.", "#...#", "#...#", "####." };
        private static readonly string[] GlyphC = { ".####", "#....", "#....", "#....", "#....", "#....", ".####" };

        private static void Letter(Image img, char c, float u, float v, float w, float h, float r, float g, float b, float a = 1f)
        {
            string[] glyph = c == 'A' ? GlyphA : c == 'B' ? GlyphB : GlyphC;
            float cw = w / 5f, ch = h / 7f;
            for (int row = 0; row < 7; row++)
                for (int col = 0; col < 5; col++)
                    if (glyph[row][col] == '#')
                        img.Rect(u + col * cw, v + row * ch, u + (col + 1) * cw, v + (row + 1) * ch, r, g, b, a);
        }

        // ------------------------------------------------------------------ wooden crate

        /// <summary>
        /// Wooden crate: a frame of planks around a strand-board panel (pressed wood flakes); the sides carry a
        /// stencilled handling row, a square code and the type letter.
        /// </summary>
        public static Image Crate(float r, float g, float b, bool top, char letter, int seed)
        {
            var img = new Image(Size, Size);
            int frame = Size / 8;
            // strand board panel: overlapping random flakes of slightly different tones
            float pr = Lerp(r, .86f, .45f), pg = Lerp(g, .7f, .45f), pb = Lerp(b, .45f, .45f);
            for (int y = 0; y < Size; y++)
                for (int x = 0; x < Size; x++)
                    img.Set(x, y, pr * .92f, pg * .92f, pb * .92f);
            for (int k = 0; k < 900; k++)
            {
                float cu = Hash(k, 1, seed), cv = Hash(k, 2, seed);
                float len = .03f + .05f * Hash(k, 3, seed), wid = .01f + .012f * Hash(k, 4, seed);
                double ang = Hash(k, 5, seed) * Math.PI;
                float tone = .8f + .32f * Hash(k, 6, seed);
                float du = (float)Math.Cos(ang) * len / 2f, dv = (float)Math.Sin(ang) * len / 2f;
                Line(img, cu - du, cv - dv, cu + du, cv + dv, wid, pr * tone, pg * tone, pb * tone, .9f);
            }
            // frame planks with grain
            for (int y = 0; y < Size; y++)
                for (int x = 0; x < Size; x++)
                {
                    bool vertical = x < frame || x >= Size - frame;
                    bool horizontal = y < frame || y >= Size - frame;
                    if (!vertical && !horizontal) continue;
                    int plank = horizontal ? (y < frame ? 0 : 1) : (x < frame ? 2 : 3);
                    int along = horizontal ? x : y, across = horizontal ? y : x;
                    float tone = .9f + .14f * Hash(plank, 1, seed);
                    float grain = .9f + .1f * (float)Math.Sin(across * .9f + 18f * Fbm(along / 40f, across / 6f, seed + plank, 8));
                    float f = tone * grain;
                    img.Set(x, y, r * 1.12f * f, g * 1.12f * f, b * 1.1f * f);
                }
            for (int i = 0; i < Size; i++)
            {
                img.Shade(frame, i, .55f); img.Shade(Size - 1 - frame, i, .55f);
                img.Shade(i, frame, .55f); img.Shade(i, Size - 1 - frame, .55f);
                img.Shade(0, i, .6f); img.Shade(Size - 1, i, .6f); img.Shade(i, 0, .6f); img.Shade(i, Size - 1, .6f);
            }
            // nails
            float nc = frame / 2f / Size;
            foreach (float nu in new[] { nc, 1f - nc })
                foreach (float nv in new[] { nc, 1f - nc })
                    Disc(img, nu, nv, .012f, .25f, .24f, .22f);
            if (!top)
            {
                float ir = .17f, ig = .11f, ib = .06f;
                PictoRow(img, .52f, .2f, .1f, ir, ig, ib);
                SquareCode(img, .2f, .22f, .15f, seed);
                Letter(img, letter, .22f, .58f, .1f, .16f, ir, ig, ib, .85f);
            }
            return img;
        }

        private static float Lerp(float a, float b, float t) => a + (b - a) * t;
    }
}
